#[test]
fn serialized_unique_index_check_rejects_duplicates_and_exempts_null_tuples()
-> Result<(), Box<dyn std::error::Error>> {
    let fixture = Fixture::new();
    let database = initialize(&fixture.path())?;
    let first_row = key(31);
    let first_index = index_key(&first_row);
    commit_rows_and_indexes(
        &database,
        id(31),
        id(9),
        9_999,
        &[RowWrite {
            key: first_row,
            expected_version: None,
            payload: Some(b"first".to_vec()),
        }],
        &[IndexWrite {
            key: first_index,
            row_key: first_row,
            expected_version: None,
            present: true,
            unique: true,
            null_exempt: false,
        }],
    )?;

    let second_row = key(32);
    let second_index = index_key(&second_row);
    assert_eq!(
        commit_rows_and_indexes(
            &database,
            id(32),
            id(9),
            9_999,
            &[RowWrite {
                key: second_row,
                expected_version: None,
                payload: Some(b"duplicate".to_vec()),
            }],
            &[IndexWrite {
                key: second_index.clone(),
                row_key: second_row,
                expected_version: None,
                present: true,
                unique: true,
                null_exempt: false,
            }],
        ),
        Err(CommitError::UniqueViolation)
    );
    assert_eq!(commit_sequence(&database)?, 1);
    assert!(row(&database, &second_row)?.is_none());

    let null_index = prdb_engine::index_key::compose_key(
        [0x44; 16],
        &[0xff],
        second_row[16..].try_into().unwrap(),
    );
    assert_eq!(
        commit_rows_and_indexes(
            &database,
            id(33),
            id(9),
            9_999,
            &[RowWrite {
                key: second_row,
                expected_version: None,
                payload: Some(b"null-key".to_vec()),
            }],
            &[IndexWrite {
                key: null_index,
                row_key: second_row,
                expected_version: None,
                present: true,
                unique: true,
                null_exempt: true,
            }],
        )?,
        2
    );
    assert_eq!(row(&database, &second_row)?.unwrap().payload, b"null-key");

    let third_row = key(33);
    let third_null_index = prdb_engine::index_key::compose_key(
        [0x44; 16],
        &[0xff],
        third_row[16..].try_into().unwrap(),
    );
    assert_eq!(
        commit_rows_and_indexes(
            &database,
            id(34),
            id(9),
            9_999,
            &[RowWrite {
                key: third_row,
                expected_version: None,
                payload: Some(b"another-null-key".to_vec()),
            }],
            &[IndexWrite {
                key: third_null_index,
                row_key: third_row,
                expected_version: None,
                present: true,
                unique: true,
                null_exempt: true,
            }],
        )?,
        3
    );
    assert_eq!(
        row(&database, &third_row)?.unwrap().payload,
        b"another-null-key"
    );
    Ok(())
}

#[test]
fn foreign_key_commit_checks_child_and_parent_changes_against_final_rows()
-> Result<(), Box<dyn std::error::Error>> {
    let fixture = Fixture::new();
    let database = initialize(&fixture.path())?;
    let source_table_id = [0x55; 16];
    let target_table_id = [0x66; 16];
    let source_key = table_row_key(source_table_id, [1; 16]);
    let null_source_key = table_row_key(source_table_id, [3; 16]);
    let target_key = table_row_key(target_table_id, [2; 16]);
    let column = ColumnSchema {
        scalar_type: ScalarType::Bytea,
        nullable: true,
    };
    let foreign_key = ForeignKeyCheck {
        source_table_id,
        source_schema_version: 1,
        source_schema: vec![column.clone()],
        source_ordinals: vec![0],
        target_table_id,
        target_schema_version: 1,
        target_schema: vec![column.clone()],
        target_ordinals: vec![0],
    };
    let parent = encode_tuple(
        std::slice::from_ref(&column),
        1,
        &[Some(ScalarValue::Bytea(b"parent".to_vec()))],
    )?;
    commit_rows(
        &database,
        id(101),
        id(9),
        9_999,
        &[RowWrite {
            key: target_key,
            expected_version: None,
            payload: Some(parent.clone()),
        }],
    )?;

    let missing_parent = encode_tuple(
        std::slice::from_ref(&column),
        1,
        &[Some(ScalarValue::Bytea(b"missing".to_vec()))],
    )?;
    assert_eq!(
        commit_storage_changes(
            &database,
            CommitRequest {
                invocation_id: id(102),
                principal_id: id(9),
                retention_deadline_us: 9_999,
                rows: &[RowWrite {
                    key: source_key,
                    expected_version: None,
                    payload: Some(missing_parent),
                }],
                indexes: &[],
                foreign_keys: std::slice::from_ref(&foreign_key),
                catalog_guards: &[],
                catalog: &[],
                audit: &[],
            },
        ),
        Err(CommitError::ForeignKeyViolation)
    );
    assert!(row(&database, &source_key)?.is_none());
    assert_eq!(commit_sequence(&database)?, 1);

    let null_child = encode_tuple(std::slice::from_ref(&column), 1, &[None])?;
    assert_eq!(
        commit_storage_changes(
            &database,
            CommitRequest {
                invocation_id: id(109),
                principal_id: id(9),
                retention_deadline_us: 9_999,
                rows: &[RowWrite {
                    key: null_source_key,
                    expected_version: None,
                    payload: Some(null_child),
                }],
                indexes: &[],
                foreign_keys: std::slice::from_ref(&foreign_key),
                catalog_guards: &[],
                catalog: &[],
                audit: &[],
            },
        )?,
        2
    );

    let child = encode_tuple(
        std::slice::from_ref(&column),
        1,
        &[Some(ScalarValue::Bytea(b"parent".to_vec()))],
    )?;
    assert_eq!(
        commit_storage_changes(
            &database,
            CommitRequest {
                invocation_id: id(103),
                principal_id: id(9),
                retention_deadline_us: 9_999,
                rows: &[RowWrite {
                    key: source_key,
                    expected_version: None,
                    payload: Some(child),
                }],
                indexes: &[],
                foreign_keys: std::slice::from_ref(&foreign_key),
                catalog_guards: &[],
                catalog: &[],
                audit: &[],
            },
        )?,
        3
    );

    assert_eq!(
        commit_storage_changes(
            &database,
            CommitRequest {
                invocation_id: id(104),
                principal_id: id(9),
                retention_deadline_us: 9_999,
                rows: &[RowWrite {
                    key: target_key,
                    expected_version: Some(1),
                    payload: None,
                }],
                indexes: &[],
                foreign_keys: std::slice::from_ref(&foreign_key),
                catalog_guards: &[],
                catalog: &[],
                audit: &[],
            },
        ),
        Err(CommitError::ForeignKeyViolation)
    );
    assert!(row(&database, &target_key)?.is_some());

    assert_eq!(
        commit_storage_changes(
            &database,
            CommitRequest {
                invocation_id: id(105),
                principal_id: id(9),
                retention_deadline_us: 9_999,
                rows: &[
                    RowWrite {
                        key: source_key,
                        expected_version: Some(3),
                        payload: None,
                    },
                    RowWrite {
                        key: null_source_key,
                        expected_version: Some(2),
                        payload: None,
                    },
                    RowWrite {
                        key: target_key,
                        expected_version: Some(1),
                        payload: None,
                    },
                ],
                indexes: &[],
                foreign_keys: std::slice::from_ref(&foreign_key),
                catalog_guards: &[],
                catalog: &[],
                audit: &[],
            },
        )?,
        4
    );
    assert!(row(&database, &source_key)?.is_none());
    assert!(row(&database, &null_source_key)?.is_none());
    assert!(row(&database, &target_key)?.is_none());
    Ok(())
}

#[test]
fn foreign_key_row_visit_limit_aborts_the_whole_commit() -> Result<(), Box<dyn std::error::Error>> {
    let fixture = Fixture::new();
    let database = initialize(&fixture.path())?;
    let source_table_id = [0x55; 16];
    let target_table_id = [0x66; 16];
    let column = ColumnSchema {
        scalar_type: ScalarType::Bytea,
        nullable: true,
    };
    let parent = bytea_tuple(b"parent");
    let mut initial_rows = Vec::with_capacity(256);
    let mut updated_child_key = [0; 32];
    for row_number in 0..128u8 {
        let parent_key = table_row_key(target_table_id, [row_number; 16]);
        let child_key = table_row_key(source_table_id, [row_number; 16]);
        if row_number == 0 {
            updated_child_key = child_key;
        }
        initial_rows.push(RowWrite {
            key: parent_key,
            expected_version: None,
            payload: Some(parent.clone()),
        });
        initial_rows.push(RowWrite {
            key: child_key,
            expected_version: None,
            payload: Some(parent.clone()),
        });
    }
    commit_rows(&database, id(110), id(9), 9_999, &initial_rows)?;

    let foreign_key = ForeignKeyCheck {
        source_table_id,
        source_schema_version: 1,
        source_schema: vec![column.clone()],
        source_ordinals: vec![0],
        target_table_id,
        target_schema_version: 1,
        target_schema: vec![column],
        target_ordinals: vec![0],
    };
    let foreign_keys = vec![foreign_key; 256];
    let result = commit_storage_changes(
        &database,
        CommitRequest {
            invocation_id: id(111),
            principal_id: id(9),
            retention_deadline_us: 9_999,
            rows: &[RowWrite {
                key: updated_child_key,
                expected_version: Some(1),
                payload: Some(parent),
            }],
            indexes: &[],
            foreign_keys: &foreign_keys,
            catalog_guards: &[],
            catalog: &[],
            audit: &[],
        },
    );
    assert_eq!(result, Err(CommitError::ForeignKeyValidationLimitExceeded));
    assert_eq!(commit_sequence(&database)?, 1);
    assert_eq!(row(&database, &updated_child_key)?.unwrap().row_version, 1);
    let read = database.begin_read()?;
    let encoded_outcome = read
        .open_table(prdb_engine::schema::OUTCOMES)?
        .get(&id(111)[..])?
        .unwrap()
        .value()
        .to_vec();
    assert_eq!(
        InvocationOutcome::decode(&encoded_outcome)?.status,
        OutcomeStatus::Aborted
    );
    Ok(())
}

#[test]
fn foreign_key_comparison_key_budget_aborts_large_keys_atomically()
-> Result<(), Box<dyn std::error::Error>> {
    let fixture = Fixture::new();
    let database = initialize(&fixture.path())?;
    let source_table_id = [0x55; 16];
    let target_table_id = [0x66; 16];
    let column = ColumnSchema {
        scalar_type: ScalarType::Bytea,
        nullable: false,
    };
    let mut initial_rows = Vec::with_capacity(256);
    let mut updated_child_key = [0; 32];
    let mut updated_child_payload = Vec::new();
    for row_number in 0..128u8 {
        let mut value = vec![row_number.wrapping_add(1); 70 * 1024];
        value[..8].copy_from_slice(&(row_number as u64).to_be_bytes());
        let payload = encode_tuple(
            std::slice::from_ref(&column),
            1,
            &[Some(ScalarValue::Bytea(value))],
        )?;
        let parent_key = table_row_key(target_table_id, [row_number; 16]);
        let child_key = table_row_key(source_table_id, [row_number; 16]);
        if row_number == 0 {
            updated_child_key = child_key;
            updated_child_payload = payload.clone();
        }
        initial_rows.push(RowWrite {
            key: parent_key,
            expected_version: None,
            payload: Some(payload.clone()),
        });
        initial_rows.push(RowWrite {
            key: child_key,
            expected_version: None,
            payload: Some(payload),
        });
    }
    commit_rows(&database, id(112), id(9), 9_999, &initial_rows)?;

    let foreign_key = ForeignKeyCheck {
        source_table_id,
        source_schema_version: 1,
        source_schema: vec![column.clone()],
        source_ordinals: vec![0],
        target_table_id,
        target_schema_version: 1,
        target_schema: vec![column],
        target_ordinals: vec![0],
    };
    assert_eq!(
        commit_storage_changes(
            &database,
            CommitRequest {
                invocation_id: id(113),
                principal_id: id(9),
                retention_deadline_us: 9_999,
                rows: &[RowWrite {
                    key: updated_child_key,
                    expected_version: Some(1),
                    payload: Some(updated_child_payload),
                }],
                indexes: &[],
                foreign_keys: std::slice::from_ref(&foreign_key),
                catalog_guards: &[],
                catalog: &[],
                audit: &[],
            },
        ),
        Err(CommitError::ForeignKeyValidationLimitExceeded)
    );
    assert_eq!(commit_sequence(&database)?, 1);
    assert_eq!(row(&database, &updated_child_key)?.unwrap().row_version, 1);
    Ok(())
}

#[test]
fn dependency_graph_scan_limit_aborts_catalog_publication_atomically()
-> Result<(), Box<dyn std::error::Error>> {
    const MAX_FAMILY_RECORDS: usize = 65_536;
    let fixture = Fixture::new();
    let database = initialize(&fixture.path())?;
    let prefix = 15u16.to_be_bytes();
    let write = database.begin_write()?;
    let mut catalog = write.open_table(CATALOG)?;
    let mut existing_count = 0;
    for entry in catalog.range::<&[u8]>(prefix.as_slice()..)? {
        let (key, _) = entry?;
        if !key.value().starts_with(&prefix) {
            break;
        }
        existing_count += 1;
    }
    for sequence in 1..=(MAX_FAMILY_RECORDS - existing_count) as u64 {
        let mut dependent_id = [0xa5; 16];
        dependent_id[..8].copy_from_slice(&sequence.to_be_bytes());
        let write = dependency_write(dependent_id, [0xa6; 16], 5);
        catalog.insert(
            write.key.as_slice(),
            write.payload.as_ref().unwrap().as_slice(),
        )?;
    }
    drop(catalog);
    write.commit()?;

    let overflow = dependency_write([0xf5; 16], [0xf6; 16], 5);
    let invocation_id = id(0xf7);
    let actor = builtin_owner_id();
    let mut event = audit_event(0xf8);
    event.actor_id = Some(actor);
    event.correlation_id = invocation_id;
    event.action = AuditAction::Ddl;
    assert!(matches!(
        commit_catalog_and_audit(
            &database,
            invocation_id,
            actor,
            9_999,
            std::slice::from_ref(&overflow),
            &[event],
        ),
        Err(CommitError::InvalidCatalog)
    ));
    assert_eq!(commit_sequence(&database)?, 0);
    assert!(
        database
            .begin_read()?
            .open_table(CATALOG)?
            .get(overflow.key.as_slice())?
            .is_none()
    );
    assert_eq!(
        lookup_outcome(&database, invocation_id, actor, 1)?
            .ok_or("missing bounded dependency validation outcome")?
            .status,
        OutcomeStatus::Aborted
    );
    Ok(())
}

#[test]
fn concurrent_foreign_key_insert_and_parent_delete_cannot_both_commit()
-> Result<(), Box<dyn std::error::Error>> {
    let fixture = Fixture::new();
    let database = initialize(&fixture.path())?;
    let source_table_id = [0x55; 16];
    let target_table_id = [0x66; 16];
    let source_key = table_row_key(source_table_id, [1; 16]);
    let target_key = table_row_key(target_table_id, [2; 16]);
    let column = ColumnSchema {
        scalar_type: ScalarType::Bytea,
        nullable: true,
    };
    let foreign_key = ForeignKeyCheck {
        source_table_id,
        source_schema_version: 1,
        source_schema: vec![column.clone()],
        source_ordinals: vec![0],
        target_table_id,
        target_schema_version: 1,
        target_schema: vec![column.clone()],
        target_ordinals: vec![0],
    };
    let value = encode_tuple(
        std::slice::from_ref(&column),
        1,
        &[Some(ScalarValue::Bytea(b"parent".to_vec()))],
    )?;
    commit_rows(
        &database,
        id(106),
        id(9),
        9_999,
        &[RowWrite {
            key: target_key,
            expected_version: None,
            payload: Some(value.clone()),
        }],
    )?;
    let source_write = RowWrite {
        key: source_key,
        expected_version: None,
        payload: Some(value),
    };
    let target_write = RowWrite {
        key: target_key,
        expected_version: Some(1),
        payload: None,
    };
    let barrier = Arc::new(Barrier::new(3));
    let (child_result, parent_result) = std::thread::scope(|scope| {
        let child_barrier = barrier.clone();
        let child_fk = foreign_key.clone();
        let child_database = &database;
        let child = scope.spawn(move || {
            child_barrier.wait();
            commit_storage_changes(
                child_database,
                CommitRequest {
                    invocation_id: id(107),
                    principal_id: id(9),
                    retention_deadline_us: 9_999,
                    rows: std::slice::from_ref(&source_write),
                    indexes: &[],
                    foreign_keys: std::slice::from_ref(&child_fk),
                    catalog_guards: &[],
                    catalog: &[],
                    audit: &[],
                },
            )
        });
        let parent_barrier = barrier.clone();
        let parent_database = &database;
        let parent = scope.spawn(move || {
            parent_barrier.wait();
            commit_storage_changes(
                parent_database,
                CommitRequest {
                    invocation_id: id(108),
                    principal_id: id(9),
                    retention_deadline_us: 9_999,
                    rows: std::slice::from_ref(&target_write),
                    indexes: &[],
                    foreign_keys: std::slice::from_ref(&foreign_key),
                    catalog_guards: &[],
                    catalog: &[],
                    audit: &[],
                },
            )
        });
        barrier.wait();
        (child.join().unwrap(), parent.join().unwrap())
    });
    assert_ne!(child_result.is_ok(), parent_result.is_ok());
    assert!(matches!(
        child_result.as_ref().err().or(parent_result.as_ref().err()),
        Some(CommitError::ForeignKeyViolation)
    ));
    assert_eq!(commit_sequence(&database)?, 2);
    let read = database.begin_read()?;
    let child_exists = read.open_table(ROWS)?.get(&source_key[..])?.is_some();
    let parent_exists = read.open_table(ROWS)?.get(&target_key[..])?.is_some();
    assert_eq!(child_exists, parent_exists);
    Ok(())
}

#[test]
fn multirow_commit_assigns_one_sequence_and_conflict_aborts_the_whole_set()
-> Result<(), Box<dyn std::error::Error>> {
    let fixture = Fixture::new();
    let database = initialize(&fixture.path())?;

    assert_eq!(
        commit_rows(
            &database,
            id(1),
            id(9),
            9_999,
            &[
                RowWrite {
                    key: key(1),
                    expected_version: None,
                    payload: Some(b"a1".to_vec()),
                },
                RowWrite {
                    key: key(2),
                    expected_version: None,
                    payload: Some(b"b1".to_vec()),
                },
            ],
        )?,
        1
    );
    assert_eq!(commit_sequence(&database)?, 1);

    assert_eq!(
        commit_rows(
            &database,
            id(2),
            id(9),
            9_999,
            &[
                RowWrite {
                    key: key(1),
                    expected_version: Some(1),
                    payload: Some(b"a2".to_vec()),
                },
                RowWrite {
                    key: key(2),
                    expected_version: Some(1),
                    payload: Some(b"b2".to_vec()),
                },
            ],
        )?,
        2
    );
    assert_eq!(row(&database, &key(1))?.unwrap().row_version, 2);
    assert_eq!(row(&database, &key(2))?.unwrap().row_version, 2);

    let conflict = commit_rows(
        &database,
        id(3),
        id(9),
        9_999,
        &[
            RowWrite {
                key: key(1),
                expected_version: Some(1),
                payload: Some(b"stale".to_vec()),
            },
            RowWrite {
                key: key(2),
                expected_version: Some(2),
                payload: Some(b"must-rollback".to_vec()),
            },
        ],
    );
    assert_eq!(conflict, Err(CommitError::Conflict));
    assert_eq!(commit_sequence(&database)?, 2);
    assert_eq!(row(&database, &key(1))?.unwrap().payload, b"a2");
    assert_eq!(row(&database, &key(2))?.unwrap().payload, b"b2");
    {
        let read = database.begin_read()?;
        let outcomes = read.open_table(prdb_engine::schema::OUTCOMES)?;
        let outcome = outcomes.get(&id(2)[..])?.unwrap().value().to_vec();
        assert_eq!(
            InvocationOutcome::decode(&outcome)?,
            InvocationOutcome {
                status: OutcomeStatus::Committed,
                invocation_id: id(2),
                principal_id: id(9),
                commit_sequence: 2,
                retention_deadline_us: 9_999,
            }
        );
        let aborted = outcomes.get(&id(3)[..])?.unwrap().value().to_vec();
        assert_eq!(
            InvocationOutcome::decode(&aborted)?,
            InvocationOutcome {
                status: OutcomeStatus::Aborted,
                invocation_id: id(3),
                principal_id: id(9),
                commit_sequence: 0,
                retention_deadline_us: 9_999,
            }
        );
    }
    drop(database);
    let reopened = Database::open(fixture.path())?;
    assert_eq!(
        lookup_outcome(&reopened, id(2), id(9), 9_998)?,
        Some(InvocationOutcome {
            status: OutcomeStatus::Committed,
            invocation_id: id(2),
            principal_id: id(9),
            commit_sequence: 2,
            retention_deadline_us: 9_999,
        })
    );
    assert_eq!(lookup_outcome(&reopened, id(2), id(10), 9_998)?, None);
    assert_eq!(lookup_outcome(&reopened, id(2), id(9), 9_999)?, None);
    assert_eq!(
        lookup_outcome(&reopened, id(3), id(9), 9_998)?,
        Some(InvocationOutcome {
            status: OutcomeStatus::Aborted,
            invocation_id: id(3),
            principal_id: id(9),
            commit_sequence: 0,
            retention_deadline_us: 9_999,
        })
    );
    Ok(())
}

#[test]
fn planner_stream_estimate_allowance_falls_back_without_aborting_invocation()
-> Result<(), Box<dyn std::error::Error>> {
    use prdb_engine::authorization::{Effect, Expr, Operation, Subject};
    use prdb_engine::executor_ipc::ResolveRelationRequest;
    use prdb_engine::ipc::{IpcFrame, Operation as IpcOperation};
    use prdb_engine::optimizer_binding::{
        BindError, BoundColumn, MetadataBindError, bind_select_request_via_metadata,
    };
    use prdb_engine::optimizer_ipc::OptimizerResponse;
    use prdb_engine::optimizer_plan::{PlanNode, decode_plan_v1};
    use prdb_engine::optimizer_service::{OptimizerError, optimize_select_v1};
    use prdb_engine::planner_ipc::{
        DescribePlanRelationRequest, DescribePlanRelationResponse, DescribeRelationResponse,
        EstimatePredicateRequest, EstimatePredicateResponse, EstimateScanRequest,
        EstimateScanResponse, MAX_PLANNER_REQUESTS_PER_CONNECTION, serve_planner,
    };
    use prdb_engine::storage_manager::{
        CreatePolicyRequest, CreateTableRequest, ObjectGrantPrivilege, ObjectGrantTarget,
        PolicyKind, SetObjectGrantRequest, TableColumnDefinition,
    };
    use prdb_engine::transaction::MAX_PLANNER_ESTIMATE_REQUESTS_PER_CONNECTION;
    use std::net::Shutdown;

    let fixture = Fixture::new();
    let database = initialize(&fixture.path())?;
    let storage = StorageManager::new(&database, Duration::from_millis(100))?;
    let actor = id(0x81);
    let admin_role = builtin_owner_id();
    let mut setup_audit = identity_audit_event(0x82, admin_role, actor);
    setup_audit.action = AuditAction::AuthorityChange;
    storage
        .commit_catalog_and_audit(
            id(0x82),
            admin_role,
            9_999,
            &[
                principal_write_with_name(actor, 1, 1, "planner_stats_owner"),
                object_write_with_name(actor, 8, "planner_stats_owner"),
                membership_write(actor, admin_role),
                dependency_write(actor, admin_role, 5),
            ],
            &[setup_audit],
        )
        .map_err(|error| format!("planner fixture identity setup: {error:?}"))?;

    let mut schema_audit = identity_audit_event(0x83, actor, actor);
    schema_audit.correlation_id = id(0x83);
    let schema = storage
        .create_schema(id(0x83), actor, "planner_stats", actor, 9_999, schema_audit)
        .map_err(|error| format!("planner fixture schema creation: {error:?}"))?;
    let mut table_audit = identity_audit_event(0x84, actor, schema.schema_id);
    table_audit.correlation_id = id(0x84);
    let table = storage
        .create_table(CreateTableRequest {
            invocation_id: id(0x84),
            authenticated_actor_id: actor,
            schema_id: schema.schema_id,
            name: "observations".to_owned(),
            columns: vec![TableColumnDefinition {
                name: "value".to_owned(),
                scalar_type: ScalarType::Integer,
                nullable: true,
                generated_uuid_identity: false,
                default: None,
            }],
            retention_deadline_us: 9_999,
            audit_event: table_audit,
        })
        .map_err(|error| format!("planner fixture table creation: {error:?}"))?;

    for (audit_id, invocation_id, object_id, privilege, target) in [
        (
            0x85,
            id(0x85),
            schema.schema_id,
            ObjectGrantPrivilege::Usage,
            ObjectGrantTarget::Object,
        ),
        (
            0x86,
            id(0x86),
            table.table_id,
            ObjectGrantPrivilege::Select,
            ObjectGrantTarget::Object,
        ),
        (
            0x89,
            id(0x89),
            table.table_id,
            ObjectGrantPrivilege::Select,
            ObjectGrantTarget::Column(table.column_ids[0]),
        ),
    ] {
        let mut audit = identity_audit_event(audit_id, actor, object_id);
        audit.correlation_id = invocation_id;
        audit.action = AuditAction::AuthorityChange;
        storage
            .set_object_grant(SetObjectGrantRequest {
                invocation_id,
                authenticated_actor_id: actor,
                grantee_id: actor,
                object_id,
                privilege,
                target,
                grant: true,
                retention_deadline_us: 9_999,
                audit_event: audit,
            })
            .map_err(|error| format!("planner fixture grant creation: {error:?}"))?;
    }
    let mut policy_audit = identity_audit_event(0x87, actor, table.table_id);
    policy_audit.correlation_id = id(0x87);
    storage
        .create_policy(CreatePolicyRequest {
            invocation_id: id(0x87),
            authenticated_actor_id: actor,
            table_id: table.table_id,
            name: "planner_stats_select".to_owned(),
            kind: PolicyKind::Row,
            operation: Operation::Select,
            effect: Effect::Allow,
            recipients: vec![Subject::Principal(actor)],
            target_column_ids: Vec::new(),
            using_expression: Some(Expr::Literal(Some(ScalarValue::Boolean(true)))),
            with_check_expression: None,
            retention_deadline_us: 9_999,
            audit_event: policy_audit,
        })
        .map_err(|error| format!("planner fixture policy creation: {error:?}"))?;
    let mut column_policy_audit = identity_audit_event(0x90, actor, table.table_id);
    column_policy_audit.correlation_id = id(0x90);
    storage
        .create_policy(CreatePolicyRequest {
            invocation_id: id(0x90),
            authenticated_actor_id: actor,
            table_id: table.table_id,
            name: "planner_stats_read_value".to_owned(),
            kind: PolicyKind::Cell,
            operation: Operation::Select,
            effect: Effect::Allow,
            recipients: vec![Subject::Principal(actor)],
            target_column_ids: vec![table.column_ids[0]],
            using_expression: Some(Expr::Literal(Some(ScalarValue::Boolean(true)))),
            with_check_expression: None,
            retention_deadline_us: 9_999,
            audit_event: column_policy_audit,
        })
        .map_err(|error| format!("planner fixture column policy creation: {error:?}"))?;

    let encode_select = |schema_name: &str, relation_name: &str, column_name: &str| {
        let mut bytes = vec![0, 1, 1, 0];
        for name in [schema_name, relation_name] {
            bytes.push(name.len() as u8);
            bytes.extend_from_slice(name.as_bytes());
        }
        bytes.extend_from_slice(&1u16.to_be_bytes());
        bytes.push(column_name.len() as u8);
        bytes.extend_from_slice(column_name.as_bytes());
        bytes.extend_from_slice(&0u32.to_be_bytes());
        bytes.push(0);
        bytes
    };
    let encode_filtered_select = |schema_name: &str, relation_name: &str, column_name: &str| {
        let mut bytes = vec![0, 1, 1, 0];
        for name in [schema_name, relation_name] {
            bytes.push(name.len() as u8);
            bytes.extend_from_slice(name.as_bytes());
        }
        bytes.extend_from_slice(&1u16.to_be_bytes());
        bytes.push(column_name.len() as u8);
        bytes.extend_from_slice(column_name.as_bytes());
        let mut predicate = vec![0x20, 0, 0x10, column_name.len() as u8];
        predicate.extend_from_slice(column_name.as_bytes());
        predicate.push(0x02);
        predicate.extend_from_slice(&7i64.to_be_bytes());
        bytes.extend_from_slice(&(predicate.len() as u32).to_be_bytes());
        bytes.extend_from_slice(&predicate);
        bytes.push(1);
        bytes.extend_from_slice(&3u32.to_be_bytes());
        bytes
    };
    let mut binding_transaction = storage.begin_invocation(id(0x8a), actor, 9_999, 8, 512)?;
    {
        let mut planner_connection = binding_transaction.open_planner_metadata_connection();
        let bound = bind_select_request_via_metadata(
            &encode_select("planner_stats", "observations", "value"),
            &mut planner_connection,
        )?;
        assert_eq!(bound.schema_name, "planner_stats");
        assert_eq!(bound.schema_id, schema.schema_id);
        assert_eq!(bound.schema_version, 1);
        assert_eq!(bound.table_epoch, 3);
        assert_eq!(bound.relation_id, table.table_id);
        assert_eq!(bound.relation_name, "observations");
        assert_eq!(
            bound.projections,
            [BoundColumn {
                column_id: table.column_ids[0],
                ordinal: 0,
                scalar_type: ScalarType::Integer,
                nullable: true,
            }]
        );
        let encoded_plan = optimize_select_v1(
            &encode_select("planner_stats", "observations", "value"),
            &mut planner_connection,
        )?;
        let plan = decode_plan_v1(&encoded_plan)?;
        assert_eq!(plan.relation.schema_id, schema.schema_id);
        assert_eq!(plan.relation.schema_version, 1);
        assert_eq!(plan.relation.relation_id, table.table_id);
        assert_eq!(plan.relation.table_epoch, 3);
        assert!(
            matches!(plan.nodes.first(), Some(PlanNode::Scan { columns }) if columns == &[BoundColumn {
                column_id: table.column_ids[0],
                ordinal: 0,
                scalar_type: ScalarType::Integer,
                nullable: true,
            }])
        );
        assert!(matches!(
            optimize_select_v1(
                &encode_select("planner_stats", "hidden_or_missing", "value"),
                &mut planner_connection,
            ),
            Err(OptimizerError::Bind(MetadataBindError::Bind(
                BindError::RelationUnavailable
            )))
        ));
        assert!(matches!(
            bind_select_request_via_metadata(
                &encode_select("planner_stats", "hidden_or_missing", "value"),
                &mut planner_connection,
            ),
            Err(MetadataBindError::Bind(BindError::RelationUnavailable))
        ));
    }
    binding_transaction.abort()?;

    let cancelled_invocation_id = id(0x8d);
    let mut cancelled_estimate =
        storage.begin_invocation(cancelled_invocation_id, actor, 9_999, 8, 512)?;
    let (mut cancelled_planner_client, mut cancelled_planner_server) =
        std::os::unix::net::UnixStream::pair()?;
    cancelled_planner_client.set_read_timeout(Some(Duration::from_secs(2)))?;
    std::thread::scope(|scope| -> Result<(), Box<dyn std::error::Error>> {
        let planner = scope.spawn(|| {
            let result = serve_planner(&mut cancelled_planner_server, &mut cancelled_estimate);
            let _ = cancelled_planner_server.shutdown(Shutdown::Both);
            result
        });
        prdb_engine::ipc::write_frame(
            &mut cancelled_planner_client,
            &IpcFrame {
                operation: IpcOperation::DescribeRelation as u16,
                request_id: 1,
                payload: ResolveRelationRequest {
                    schema_name: "planner_stats".to_owned(),
                    relation_name: "observations".to_owned(),
                }
                .encode()?,
            },
        )?;
        let description = prdb_engine::ipc::read_frame(&mut cancelled_planner_client)?
            .ok_or("planner stream closed before cancellation test relation")?;
        let handle = DescribeRelationResponse::decode(&description.payload)?
            .table
            .ok_or("authorized relation was not described for cancellation test")?
            .0;
        assert_eq!(
            storage.cancel_owned_invocation(actor, cancelled_invocation_id, 9_998)?,
            prdb_engine::storage_manager::OwnerCancellationResult::Accepted
        );
        prdb_engine::ipc::write_frame(
            &mut cancelled_planner_client,
            &IpcFrame {
                operation: IpcOperation::EstimateScan as u16,
                request_id: 2,
                payload: EstimateScanRequest {
                    handle,
                    column_ids: Vec::new(),
                }
                .encode()?,
            },
        )?;
        let cancelled_response = prdb_engine::ipc::read_frame(&mut cancelled_planner_client)?;
        cancelled_planner_client.shutdown(Shutdown::Write)?;
        drop(cancelled_planner_client);
        let planner_result = planner.join().expect("planner thread panicked");
        assert!(
            cancelled_response.is_none(),
            "cancelled estimation must terminate the planner stream instead of returning a fallback response: {cancelled_response:?}"
        );
        assert!(
            planner_result.is_err(),
            "cancelled planning must abort the worker stream"
        );
        Ok(())
    })?;
    assert_eq!(
        storage
            .lookup_invocation_outcome(cancelled_invocation_id, actor, 9_998)?
            .ok_or("cancelled estimate outcome missing")?
            .status,
        OutcomeStatus::Aborted
    );

    let expired_storage = StorageManager::with_config(
        &database,
        prdb_engine::storage_manager::StorageManagerConfig {
            max_invocation_age: Duration::from_secs(1),
            ..Default::default()
        },
    )?;
    let expired_invocation_id = id(0x8e);
    let mut expired_estimate =
        expired_storage.begin_invocation(expired_invocation_id, actor, 9_999, 8, 512)?;
    let (mut expired_planner_client, mut expired_planner_server) =
        std::os::unix::net::UnixStream::pair()?;
    expired_planner_client.set_read_timeout(Some(Duration::from_secs(2)))?;
    std::thread::scope(|scope| -> Result<(), Box<dyn std::error::Error>> {
        let planner = scope.spawn(|| {
            let result = serve_planner(&mut expired_planner_server, &mut expired_estimate);
            let _ = expired_planner_server.shutdown(Shutdown::Both);
            result
        });
        prdb_engine::ipc::write_frame(
            &mut expired_planner_client,
            &IpcFrame {
                operation: IpcOperation::DescribeRelation as u16,
                request_id: 1,
                payload: ResolveRelationRequest {
                    schema_name: "planner_stats".to_owned(),
                    relation_name: "observations".to_owned(),
                }
                .encode()?,
            },
        )?;
        let description = prdb_engine::ipc::read_frame(&mut expired_planner_client)?
            .ok_or("planner stream closed before expiry test relation")?;
        let handle = DescribeRelationResponse::decode(&description.payload)?
            .table
            .ok_or("authorized relation was not described for expiry test")?
            .0;
        std::thread::sleep(Duration::from_millis(1_100));
        prdb_engine::ipc::write_frame(
            &mut expired_planner_client,
            &IpcFrame {
                operation: IpcOperation::EstimateScan as u16,
                request_id: 2,
                payload: EstimateScanRequest {
                    handle,
                    column_ids: Vec::new(),
                }
                .encode()?,
            },
        )?;
        let expired_response = prdb_engine::ipc::read_frame(&mut expired_planner_client)?;
        expired_planner_client.shutdown(Shutdown::Write)?;
        drop(expired_planner_client);
        let planner_result = planner.join().expect("planner thread panicked");
        assert!(
            expired_response.is_none(),
            "expired estimation must terminate the planner stream instead of returning a fallback response: {expired_response:?}"
        );
        assert!(
            planner_result.is_err(),
            "expired planning must abort the worker stream"
        );
        Ok(())
    })?;
    assert_eq!(
        expired_storage
            .lookup_invocation_outcome(expired_invocation_id, actor, 9_998)?
            .ok_or("expired estimate outcome missing")?
            .status,
        OutcomeStatus::Aborted
    );

    let mut transaction = storage.begin_invocation(id(0x88), actor, 9_999, 8, 512)?;
    transaction.stage_put(
        prdb_engine::overlay::RowId {
            table: table.table_id,
            row: id(0x8c),
        },
        &encode_tuple(
            &[ColumnSchema {
                scalar_type: ScalarType::Integer,
                nullable: true,
            }],
            1,
            &[Some(ScalarValue::Integer(7))],
        )?,
    )?;
    let (mut client, mut server) = std::os::unix::net::UnixStream::pair()?;
    std::thread::scope(|scope| -> Result<(), Box<dyn std::error::Error>> {
        let planner = scope.spawn(|| serve_planner(&mut server, &mut transaction));
        prdb_engine::ipc::write_frame(
            &mut client,
            &IpcFrame {
                operation: IpcOperation::DescribeRelation as u16,
                request_id: 1,
                payload: ResolveRelationRequest {
                    schema_name: "planner_stats".to_owned(),
                    relation_name: "observations".to_owned(),
                }
                .encode()?,
            },
        )?;
        let description = prdb_engine::ipc::read_frame(&mut client)?
            .ok_or("planner stream closed after relation description")?;
        let (handle, _) = DescribeRelationResponse::decode(&description.payload)?
            .table
            .ok_or("authorized relation was not described")?;

        prdb_engine::ipc::write_frame(
            &mut client,
            &IpcFrame {
                operation: IpcOperation::DescribePlanRelation as u16,
                request_id: 2,
                payload: DescribePlanRelationRequest {
                    schema_name: "planner_stats".to_owned(),
                    relation_name: "observations".to_owned(),
                    include_scan_estimate: true,
                }
                .encode()?,
            },
        )?;
        let plan_relation = prdb_engine::ipc::read_frame(&mut client)?
            .ok_or("planner stream closed before plan relation description")?;
        let plan_relation_response = DescribePlanRelationResponse::decode(&plan_relation.payload)?;
        assert!(!plan_relation_response.proven_empty);
        assert_eq!(plan_relation_response.visible_rows_estimate, Some(1));
        let plan_relation = plan_relation_response
            .relation
            .ok_or("authorized plan relation was not described")?;
        assert_eq!(plan_relation.schema_id, schema.schema_id);
        assert_eq!(plan_relation.schema_version, 1);
        assert_eq!(plan_relation.table_epoch, 3);
        assert_eq!(plan_relation.relation.relation_id, table.table_id);

        let estimate_predicate = prdb_engine::optimizer_binding::BoundPredicate::Compare {
            operator: prdb_engine::optimizer_request::Comparison::Equal,
            left: Box::new(prdb_engine::optimizer_binding::BoundPredicate::Column(
                BoundColumn {
                    column_id: table.column_ids[0],
                    ordinal: 0,
                    scalar_type: ScalarType::Integer,
                    nullable: true,
                },
            )),
            right: Box::new(prdb_engine::optimizer_binding::BoundPredicate::Integer(7)),
        };
        prdb_engine::ipc::write_frame(
            &mut client,
            &IpcFrame {
                operation: IpcOperation::EstimateScan as u16,
                request_id: 3,
                payload: EstimatePredicateRequest::from_bound_predicate(
                    "planner_stats".to_owned(),
                    "observations".to_owned(),
                    &estimate_predicate,
                )?
                .encode()?,
            },
        )?;
        let predicate_estimate = prdb_engine::ipc::read_frame(&mut client)?
            .ok_or("planner stream closed before predicate estimate")?;
        assert_eq!(
            EstimatePredicateResponse::decode(&predicate_estimate.payload)?,
            EstimatePredicateResponse::Exact {
                visible_rows: 1,
                matching_rows: 1,
            }
        );

        for request_id in 4..(2 + MAX_PLANNER_ESTIMATE_REQUESTS_PER_CONNECTION as u64) {
            prdb_engine::ipc::write_frame(
                &mut client,
                &IpcFrame {
                    operation: IpcOperation::EstimateScan as u16,
                    request_id,
                    payload: EstimateScanRequest {
                        handle: handle.clone(),
                        column_ids: Vec::new(),
                    }
                    .encode()?,
                },
            )?;
            let response = prdb_engine::ipc::read_frame(&mut client)?
                .ok_or("planner stream closed before allowance exhaustion")?;
            assert_eq!(
                EstimateScanResponse::decode(&response.payload)?,
                EstimateScanResponse::Exact(prdb_engine::statistics::AuthorizedScanSummary {
                    visible_rows: 1,
                    columns: vec![prdb_engine::statistics::ColumnPopulation {
                        readable_values: 1,
                        nulls: 0,
                        redacted: 0,
                    }],
                })
            );
        }

        let exhausted_id = 2 + MAX_PLANNER_ESTIMATE_REQUESTS_PER_CONNECTION as u64;
        prdb_engine::ipc::write_frame(
            &mut client,
            &IpcFrame {
                operation: IpcOperation::EstimateScan as u16,
                request_id: exhausted_id,
                payload: EstimateScanRequest {
                    handle,
                    column_ids: Vec::new(),
                }
                .encode()?,
            },
        )?;
        let exhausted = prdb_engine::ipc::read_frame(&mut client)?
            .ok_or("planner stream closed on estimate fallback")?;
        assert_eq!(
            EstimateScanResponse::decode(&exhausted.payload)?,
            EstimateScanResponse::Unknown
        );

        let fallback_id = exhausted_id + 1;
        assert!(fallback_id < MAX_PLANNER_REQUESTS_PER_CONNECTION as u64);
        prdb_engine::ipc::write_frame(
            &mut client,
            &IpcFrame {
                operation: IpcOperation::DescribePlanRelation as u16,
                request_id: fallback_id,
                payload: DescribePlanRelationRequest {
                    schema_name: "planner_stats".to_owned(),
                    relation_name: "observations".to_owned(),
                    include_scan_estimate: true,
                }
                .encode()?,
            },
        )?;
        let fallback = prdb_engine::ipc::read_frame(&mut client)?
            .ok_or("planner stream closed after estimate fallback")?;
        let fallback = DescribePlanRelationResponse::decode(&fallback.payload)?;
        assert!(!fallback.proven_empty);
        assert_eq!(fallback.visible_rows_estimate, None);
        assert!(fallback.relation.is_some());
        client.shutdown(Shutdown::Write)?;
        drop(client);

        planner
            .join()
            .expect("planner server thread panicked")
            .map_err(|error| format!("planner server failed: {error:?}"))?;
        Ok(())
    })?;
    assert!(transaction.check_deadline().is_ok());

    let (mut executor_client, mut executor_storage) = std::os::unix::net::UnixStream::pair()?;
    std::thread::scope(|scope| -> Result<(), Box<dyn std::error::Error>> {
        let executor = scope.spawn(|| {
            prdb_engine::executor_ipc::serve_executor(&mut executor_storage, &mut transaction)
        });
        for (request_id, relation_name) in [(1, "observations"), (2, "hidden_or_missing")] {
            prdb_engine::ipc::write_frame(
                &mut executor_client,
                &IpcFrame {
                    operation: IpcOperation::ResolvePlanRelation as u16,
                    request_id,
                    payload: ResolveRelationRequest {
                        schema_name: "planner_stats".to_owned(),
                        relation_name: relation_name.to_owned(),
                    }
                    .encode()?,
                },
            )?;
            let response = prdb_engine::ipc::read_frame(&mut executor_client)?
                .ok_or("executor stream closed before plan relation response")?;
            let decoded = DescribePlanRelationResponse::decode(&response.payload)?;
            let relation = decoded.relation;
            if request_id == 1 {
                assert!(!decoded.proven_empty);
                let relation =
                    relation.ok_or("executor did not re-resolve authorized plan relation")?;
                assert_eq!(relation.schema_id, schema.schema_id);
                assert_eq!(relation.schema_version, 1);
                assert_eq!(relation.table_epoch, 3);
                assert_eq!(relation.relation.relation_id, table.table_id);
                assert_eq!(relation.relation.columns[0].column_id, table.column_ids[0]);
            } else {
                assert!(relation.is_none());
            }
        }
        executor_client.shutdown(Shutdown::Write)?;
        drop(executor_client);
        executor
            .join()
            .expect("executor metadata server thread panicked")
            .map_err(|error| format!("executor metadata server failed: {error:?}"))?;
        Ok(())
    })?;

    let mut optimizer_metadata_transaction =
        storage.begin_invocation(id(0x8b), actor, 9_999, 8, 512)?;
    let (optimizer_submission_worker, mut optimizer_client) =
        std::os::unix::net::UnixStream::pair()?;
    let (optimizer_planner_worker, mut optimizer_planner_storage) =
        std::os::unix::net::UnixStream::pair()?;
    use std::os::fd::AsRawFd;
    use std::os::unix::process::CommandExt;
    use std::process::{Command, Stdio};
    let submission_fd = optimizer_submission_worker.as_raw_fd();
    let planner_fd = optimizer_planner_worker.as_raw_fd();
    let mut optimizer = Command::new(env!("CARGO_BIN_EXE_prdb-optimizer"));
    optimizer
        .arg("--submission-fd")
        .arg(submission_fd.to_string())
        .arg("--planner-fd")
        .arg(planner_fd.to_string())
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null());
    // SAFETY: the child callback touches only the two live Unix-stream file
    // descriptors captured above before exec, clearing their close-on-exec
    // flag so the optimizer receives the intended channel endpoints.
    unsafe {
        optimizer.pre_exec(move || {
            for descriptor in [submission_fd, planner_fd] {
                // SAFETY: fcntl operates on inherited descriptors in the child.
                let flags = libc::fcntl(descriptor, libc::F_GETFD);
                if flags < 0
                    || libc::fcntl(descriptor, libc::F_SETFD, flags & !libc::FD_CLOEXEC) < 0
                {
                    return Err(std::io::Error::last_os_error());
                }
            }
            Ok(())
        });
    }
    let mut optimizer = optimizer.spawn()?;
    drop(optimizer_submission_worker);
    drop(optimizer_planner_worker);
    optimizer_client.set_read_timeout(Some(Duration::from_secs(5)))?;
    let mut filtered_plan_for_resolution = None;
    std::thread::scope(|scope| -> Result<(), Box<dyn std::error::Error>> {
        let planner_thread = scope.spawn(|| {
            serve_planner(
                &mut optimizer_planner_storage,
                &mut optimizer_metadata_transaction,
            )
        });
        prdb_engine::ipc::write_frame(
            &mut optimizer_client,
            &IpcFrame {
                operation: IpcOperation::OptimizeSelect as u16,
                request_id: 1,
                payload: Vec::new(),
            },
        )?;
        let invalid_frame = prdb_engine::ipc::read_frame(&mut optimizer_client)?
            .ok_or("optimizer stream closed after a malformed request")?;
        assert_eq!(invalid_frame.request_id, 1);
        assert_eq!(
            OptimizerResponse::decode(&invalid_frame.payload)?.status,
            prdb_engine::optimizer_ipc::OptimizerStatus::InvalidRequest
        );
        prdb_engine::ipc::write_frame(
            &mut optimizer_client,
            &IpcFrame {
                operation: IpcOperation::OptimizeSelect as u16,
                request_id: 2,
                payload: encode_select("planner_stats", "observations", "value"),
            },
        )?;
        let optimizer_frame = prdb_engine::ipc::read_frame(&mut optimizer_client)?
            .ok_or("optimizer stream closed without a plan response")?;
        assert_eq!(
            optimizer_frame.operation,
            IpcOperation::OptimizeSelect as u16
        );
        assert_eq!(optimizer_frame.request_id, 2);
        let optimizer_response = OptimizerResponse::decode(&optimizer_frame.payload)?;
        assert_eq!(
            optimizer_response.status,
            prdb_engine::optimizer_ipc::OptimizerStatus::Success
        );
        let plan = decode_plan_v1(
            optimizer_response
                .plan
                .as_deref()
                .ok_or("successful optimizer response omitted its plan")?,
        )?;
        assert_eq!(plan.relation.schema_id, schema.schema_id);
        assert_eq!(plan.relation.relation_id, table.table_id);
        assert!(plan.empty_view_hint);
        prdb_engine::ipc::write_frame(
            &mut optimizer_client,
            &IpcFrame {
                operation: IpcOperation::OptimizeSelect as u16,
                request_id: 3,
                payload: encode_filtered_select("planner_stats", "observations", "value"),
            },
        )?;
        let filtered_frame = prdb_engine::ipc::read_frame(&mut optimizer_client)?
            .ok_or("optimizer stream closed without a filtered plan response")?;
        assert_eq!(filtered_frame.request_id, 3);
        let filtered_response = OptimizerResponse::decode(&filtered_frame.payload)?;
        assert_eq!(
            filtered_response.status,
            prdb_engine::optimizer_ipc::OptimizerStatus::Success
        );
        let filtered_plan_bytes = filtered_response
            .plan
            .as_deref()
            .ok_or("successful filtered response omitted its plan")?;
        let filtered_plan = decode_plan_v1(filtered_plan_bytes)?;
        assert!(matches!(
            filtered_plan.nodes.get(1),
            Some(PlanNode::Filter(prdb_engine::optimizer_binding::BoundPredicate::Compare {
                operator,
                left,
                right,
                ..
            })) if *operator == prdb_engine::optimizer_request::Comparison::Equal
                && matches!(left.as_ref(), prdb_engine::optimizer_binding::BoundPredicate::Column(column) if column.column_id == table.column_ids[0])
                && matches!(right.as_ref(), prdb_engine::optimizer_binding::BoundPredicate::Integer(7))
        ));
        filtered_plan_for_resolution = Some(filtered_plan.clone());
        prdb_engine::ipc::write_frame(
            &mut optimizer_client,
            &IpcFrame {
                operation: IpcOperation::OptimizeSelect as u16,
                request_id: 4,
                payload: encode_select("planner_stats", "hidden_or_missing", "value"),
            },
        )?;
        let unavailable_frame = prdb_engine::ipc::read_frame(&mut optimizer_client)?
            .ok_or("optimizer stream closed without an unavailable response")?;
        assert_eq!(unavailable_frame.request_id, 4);
        assert_eq!(
            OptimizerResponse::decode(&unavailable_frame.payload)?.status,
            prdb_engine::optimizer_ipc::OptimizerStatus::Unavailable
        );
        optimizer_client.shutdown(Shutdown::Write)?;
        drop(optimizer_client);
        let status = optimizer.wait()?;
        assert!(status.success(), "optimizer child exited with {status}");
        planner_thread
            .join()
            .expect("planner storage thread panicked")
            .map_err(|error| format!("planner storage stream failed: {error:?}"))?;
        Ok(())
    })?;
    let filtered_plan =
        filtered_plan_for_resolution.ok_or("optimizer did not return a filtered plan")?;
    let (mut executor_plan_client, mut executor_plan_storage) =
        std::os::unix::net::UnixStream::pair()?;
    std::thread::scope(|scope| -> Result<(), Box<dyn std::error::Error>> {
        let executor = scope.spawn(|| {
            prdb_engine::executor_ipc::serve_executor(
                &mut executor_plan_storage,
                &mut optimizer_metadata_transaction,
            )
        });
        prdb_engine::ipc::write_frame(
            &mut executor_plan_client,
            &IpcFrame {
                operation: IpcOperation::ResolvePlanRelation as u16,
                request_id: 1,
                payload: ResolveRelationRequest {
                    schema_name: filtered_plan.relation.schema_name.clone(),
                    relation_name: filtered_plan.relation.relation_name.clone(),
                }
                .encode()?,
            },
        )?;
        let resolved_frame = prdb_engine::ipc::read_frame(&mut executor_plan_client)?
            .ok_or("executor stream closed without plan identity response")?;
        let resolved_relation = DescribePlanRelationResponse::decode(&resolved_frame.payload)?
            .relation
            .ok_or("executor could not independently resolve filtered plan relation")?;
        assert_eq!(
            resolved_relation.schema_id,
            filtered_plan.relation.schema_id
        );
        assert_eq!(
            resolved_relation.schema_version,
            filtered_plan.relation.schema_version
        );
        assert_eq!(
            resolved_relation.table_epoch,
            filtered_plan.relation.table_epoch
        );
        assert_eq!(
            resolved_relation.relation.relation_id,
            filtered_plan.relation.relation_id
        );
        let planned_scan_columns = match filtered_plan.nodes.first() {
            Some(PlanNode::Scan { columns }) => columns,
            _ => return Err("filtered plan did not begin with a scan".into()),
        };
        assert_eq!(
            planned_scan_columns.len(),
            resolved_relation.relation.columns.len()
        );
        for planned_column in planned_scan_columns {
            let declared_column = resolved_relation
                .relation
                .columns
                .iter()
                .find(|column| column.ordinal == planned_column.ordinal)
                .ok_or("executor metadata omitted a planned scan column")?;
            assert_eq!(declared_column.column_id, planned_column.column_id);
            assert_eq!(declared_column.scalar_type, planned_column.scalar_type);
            assert_eq!(declared_column.nullable, planned_column.nullable);
        }
        prdb_engine::ipc::write_frame(
            &mut executor_plan_client,
            &IpcFrame {
                operation: IpcOperation::ResolveRelation as u16,
                request_id: 2,
                payload: ResolveRelationRequest {
                    schema_name: filtered_plan.relation.schema_name.clone(),
                    relation_name: filtered_plan.relation.relation_name.clone(),
                }
                .encode()?,
            },
        )?;
        let capability_frame = prdb_engine::ipc::read_frame(&mut executor_plan_client)?
            .ok_or("executor stream closed without a relation capability")?;
        assert_eq!(capability_frame.request_id, 2);
        let (executor_handle, _) = match prdb_engine::executor_ipc::ResolveRelationResponse::decode(
            &capability_frame.payload,
        )? {
            prdb_engine::executor_ipc::ResolveRelationResponse::Resolved {
                handle,
                description,
            } => {
                assert_eq!(description.relation_id, filtered_plan.relation.relation_id);
                (handle, description)
            }
            prdb_engine::executor_ipc::ResolveRelationResponse::Unavailable => {
                return Err("executor denied the validated plan relation".into());
            }
        };
        prdb_engine::ipc::write_frame(
            &mut executor_plan_client,
            &IpcFrame {
                operation: IpcOperation::OpenScan as u16,
                request_id: 3,
                payload: prdb_engine::executor_ipc::OpenScanRequest {
                    relation: executor_handle,
                    column_ids: planned_scan_columns
                        .iter()
                        .map(|column| column.column_id)
                        .collect(),
                }
                .encode()?,
            },
        )?;
        let scan_frame = prdb_engine::ipc::read_frame(&mut executor_plan_client)?
            .ok_or("executor stream closed without a scan cursor")?;
        assert_eq!(scan_frame.request_id, 3);
        let scan_cursor = prdb_engine::executor_ipc::OpenScanResponse::decode(&scan_frame.payload)?;
        prdb_engine::ipc::write_frame(
            &mut executor_plan_client,
            &IpcFrame {
                operation: IpcOperation::NextBatch as u16,
                request_id: 4,
                payload: prdb_engine::executor_ipc::NextBatchRequest {
                    cursor: scan_cursor.cursor,
                    max_scanned: 8,
                    max_bytes: 4096,
                }
                .encode()?,
            },
        )?;
        let batch_frame = prdb_engine::ipc::read_frame(&mut executor_plan_client)?
            .ok_or("executor stream closed without a scan batch")?;
        assert_eq!(batch_frame.request_id, 4);
        let batch = prdb_engine::executor_ipc::NextBatchResponse::decode(&batch_frame.payload)?;
        assert!(batch.rows.is_empty());
        assert!(batch.continuation.is_none());
        executor_plan_client.shutdown(Shutdown::Write)?;
        drop(executor_plan_client);
        executor
            .join()
            .expect("executor plan metadata thread panicked")
            .map_err(|error| format!("executor plan metadata stream failed: {error:?}"))?;
        Ok(())
    })?;
    optimizer_metadata_transaction.abort()?;
    Ok(())
}

#[test]
fn catalog_backed_executor_generates_uuid_identity_and_rejects_override_and_update()
-> Result<(), Box<dyn std::error::Error>> {
    use prdb_engine::authorization::{Effect, Expr, Operation, Subject};
    use prdb_engine::storage_manager::{
        CreatePolicyRequest, CreateTableRequest, ObjectGrantPrivilege, ObjectGrantTarget,
        PolicyKind, SetObjectGrantRequest, TableColumnDefinition,
    };
    use prdb_engine::transaction::{InsertInput, TransactionError};
    use prdb_engine::tuple::FieldPatch;

    let fixture = Fixture::new();
    let database = initialize(&fixture.path())?;
    let storage = StorageManager::new(&database, Duration::from_millis(100))?;
    let admin_role = builtin_owner_id();
    let actor = id(0x91);
    let mut setup_audit = identity_audit_event(0x92, admin_role, actor);
    setup_audit.action = AuditAction::AuthorityChange;
    storage
        .commit_catalog_and_audit(
            id(0x92),
            admin_role,
            9_999,
            &[
                principal_write_with_name(actor, 1, 1, "generated_identity_owner"),
                object_write_with_name(actor, 8, "generated_identity_owner"),
                membership_write(actor, admin_role),
                dependency_write(actor, admin_role, 5),
            ],
            &[setup_audit],
        )
        .map_err(|error| format!("generated identity actor setup: {error:?}"))?;

    let schema_invocation = id(0x93);
    let mut schema_audit = identity_audit_event(0x93, actor, actor);
    schema_audit.correlation_id = schema_invocation;
    let schema = storage
        .create_schema(
            schema_invocation,
            actor,
            "generated_identity",
            actor,
            9_999,
            schema_audit,
        )
        .map_err(|error| format!("generated identity schema creation: {error:?}"))?;

    let table_invocation = id(0x94);
    let mut table_audit = identity_audit_event(0x94, actor, schema.schema_id);
    table_audit.correlation_id = table_invocation;
    let table = storage
        .create_table(CreateTableRequest {
            invocation_id: table_invocation,
            authenticated_actor_id: actor,
            schema_id: schema.schema_id,
            name: "records".to_owned(),
            columns: vec![TableColumnDefinition {
                name: "record_id".to_owned(),
                scalar_type: ScalarType::Uuid,
                nullable: false,
                generated_uuid_identity: true,
                default: None,
            }],
            retention_deadline_us: 9_999,
            audit_event: table_audit,
        })
        .map_err(|error| format!("generated identity table creation: {error:?}"))?;

    for (ordinal, (object_id, privilege, target)) in [
        (
            schema.schema_id,
            ObjectGrantPrivilege::Usage,
            ObjectGrantTarget::Object,
        ),
        (
            table.table_id,
            ObjectGrantPrivilege::Select,
            ObjectGrantTarget::Object,
        ),
        (
            table.table_id,
            ObjectGrantPrivilege::Insert,
            ObjectGrantTarget::Object,
        ),
        (
            table.table_id,
            ObjectGrantPrivilege::Update,
            ObjectGrantTarget::Object,
        ),
    ]
    .into_iter()
    .enumerate()
    {
        let invocation_id = id(0x95 + ordinal as u8);
        let mut grant_audit = identity_audit_event(0x95 + ordinal as u8, actor, object_id);
        grant_audit.correlation_id = invocation_id;
        grant_audit.action = AuditAction::AuthorityChange;
        storage
            .set_object_grant(SetObjectGrantRequest {
                invocation_id,
                authenticated_actor_id: actor,
                grantee_id: actor,
                object_id,
                privilege,
                target,
                grant: true,
                retention_deadline_us: 9_999,
                audit_event: grant_audit,
            })
            .map_err(|error| format!("generated identity grant creation: {error:?}"))?;
    }

    let policy_invocation = id(0x9a);
    let mut policy_audit = identity_audit_event(0x9a, actor, table.table_id);
    policy_audit.correlation_id = policy_invocation;
    storage
        .create_policy(CreatePolicyRequest {
            invocation_id: policy_invocation,
            authenticated_actor_id: actor,
            table_id: table.table_id,
            name: "generated_identity_insert".to_owned(),
            kind: PolicyKind::Row,
            operation: Operation::Insert,
            effect: Effect::Allow,
            recipients: vec![Subject::Principal(actor)],
            target_column_ids: Vec::new(),
            using_expression: None,
            with_check_expression: Some(Expr::Literal(Some(ScalarValue::Boolean(true)))),
            retention_deadline_us: 9_999,
            audit_event: policy_audit,
        })
        .map_err(|error| format!("generated identity INSERT policy creation: {error:?}"))?;

    let generated_column = ColumnSchema {
        scalar_type: ScalarType::Uuid,
        nullable: false,
    };
    let mut override_invocation = storage.begin_invocation(id(0x99), actor, 9_999, 8, 512)?;
    {
        let mut executor = override_invocation.open_executor_metadata_connection();
        let (relation, _) = executor
            .resolve_relation("generated_identity", "records")
            .map_err(|error| format!("generated identity relation resolve: {error:?}"))?
            .ok_or("generated identity relation was not visible")?;
        assert!(matches!(
            executor.stage_insert(
                &relation,
                &[InsertInput::Value(Some(ScalarValue::Uuid([0x9a; 16])))],
            ),
            Err(TransactionError::InvalidContext)
        ));
    }
    assert_eq!(
        lookup_outcome(&database, id(0x99), actor, 1)?
            .ok_or("generated identity override has no durable outcome")?
            .status,
        OutcomeStatus::Aborted
    );

    let mut update_invocation = storage.begin_invocation(id(0x9b), actor, 9_999, 8, 512)?;
    {
        let mut executor = update_invocation.open_executor_metadata_connection();
        let (relation, _) = executor
            .resolve_relation("generated_identity", "records")
            .map_err(|error| format!("generated identity relation resolve: {error:?}"))?
            .ok_or("generated identity relation was not visible")?;
        let row_handle = executor
            .stage_insert(&relation, &[InsertInput::Default])
            .map_err(|error| format!("generated identity default insert: {error:?}"))?;
        assert!(matches!(
            executor.stage_update(
                &row_handle,
                &[FieldPatch {
                    ordinal: 0,
                    value: Some(ScalarValue::Uuid([0x9c; 16])),
                }],
            ),
            Err(TransactionError::InvalidContext)
        ));
    }
    assert_eq!(
        lookup_outcome(&database, id(0x9b), actor, 1)?
            .ok_or("generated identity update has no durable outcome")?
            .status,
        OutcomeStatus::Aborted
    );

    let mut insert_invocation = storage.begin_invocation(id(0x9d), actor, 9_999, 8, 512)?;
    let row_id = {
        let mut executor = insert_invocation.open_executor_metadata_connection();
        let (relation, _) = executor
            .resolve_relation("generated_identity", "records")
            .map_err(|error| format!("generated identity relation resolve: {error:?}"))?
            .ok_or("generated identity relation was not visible")?;
        let row_handle = executor
            .stage_insert(&relation, &[InsertInput::Default])
            .map_err(|error| format!("generated identity default insert: {error:?}"))?;
        executor.revalidate_row_handle(&row_handle)?
    };
    let payload = insert_invocation
        .read(row_id)?
        .ok_or("generated identity row was not staged")?;
    let tuple = decode_tuple(std::slice::from_ref(&generated_column), 1, &payload)?;
    let generated_id = match tuple.values.first() {
        Some(Some(ScalarValue::Uuid(value))) if *value != [0; 16] => *value,
        _ => return Err("storage did not materialize a nonzero UUID identity".into()),
    };
    insert_invocation.commit()?;

    let stored = row(&database, &table_row_key(table.table_id, row_id.row))?
        .ok_or("committed generated identity row was not stored")?;
    let committed_tuple =
        decode_tuple(std::slice::from_ref(&generated_column), 1, &stored.payload)?;
    assert_eq!(
        committed_tuple.values,
        [Some(ScalarValue::Uuid(generated_id))]
    );
    assert_eq!(
        lookup_outcome(&database, id(0x9d), actor, 1)?
            .ok_or("generated identity insert has no durable outcome")?
            .status,
        OutcomeStatus::Committed
    );

    // Exercise the commit-time collision guard with a deterministic UUID. This
    // low-level staging entry point is trusted-only; the executor path above
    // remains the only caller-facing path that materializes generated values.
    let schema_target = prdb_engine::authorization::AccessTarget::Schema(schema.schema_id);
    let table_target = prdb_engine::authorization::AccessTarget::Table(table.table_id);
    let context = prdb_engine::authorization::AuthorizationContext {
        principal_id: actor,
        role_ids: Default::default(),
        scope: [
            (Operation::Usage, schema_target),
            (Operation::Insert, table_target),
        ]
        .into(),
    };
    let grants = [
        prdb_engine::authorization::Grant {
            subject: Subject::Principal(actor),
            operation: Operation::Usage,
            target: schema_target,
        },
        prdb_engine::authorization::Grant {
            subject: Subject::Principal(actor),
            operation: Operation::Insert,
            target: table_target,
        },
    ];
    let policies = [prdb_engine::authorization::Policy {
        subjects: vec![Subject::Principal(actor)],
        operation: Operation::Insert,
        target: table_target,
        effect: Effect::Allow,
        using: None,
        with_check: Some(Expr::Literal(Some(ScalarValue::Boolean(true)))),
    }];
    let projection = prdb_engine::authorization::AuthorizedProjection {
        columns: std::slice::from_ref(&generated_column),
        column_ids: &table.column_ids,
        schema_version: 1,
        schema_id: schema.schema_id,
        context: &context,
        grants: &grants,
        policies: &policies,
        checks: &[],
        policy_driving_columns: &[],
        dependencies: &[],
    };
    let mut duplicate = prdb_engine::transaction::InvocationTransaction::begin(
        &database,
        id(0x9e),
        actor,
        9_999,
        8,
        512,
    )?;
    duplicate.stage_insert_authorized(
        prdb_engine::overlay::RowId {
            table: table.table_id,
            row: id(0x9f),
        },
        &projection,
        &[Some(ScalarValue::Uuid(generated_id))],
        &table.column_ids,
    )?;
    assert!(matches!(
        duplicate.commit(),
        Err(prdb_engine::transaction::TransactionError::Commit(
            prdb_engine::commit::CommitError::UniqueViolation
        ))
    ));
    assert_eq!(
        lookup_outcome(&database, id(0x9e), actor, 1)?
            .ok_or("generated identity collision has no durable outcome")?
            .status,
        OutcomeStatus::Aborted
    );

    let mut concurrent_identity = generated_id;
    concurrent_identity[0] ^= 1;
    let mut left = prdb_engine::transaction::InvocationTransaction::begin(
        &database,
        id(0xa2),
        actor,
        9_999,
        8,
        512,
    )?;
    let mut right = prdb_engine::transaction::InvocationTransaction::begin(
        &database,
        id(0xa3),
        actor,
        9_999,
        8,
        512,
    )?;
    left.stage_insert_authorized(
        prdb_engine::overlay::RowId {
            table: table.table_id,
            row: id(0xa0),
        },
        &projection,
        &[Some(ScalarValue::Uuid(concurrent_identity))],
        &table.column_ids,
    )?;
    right.stage_insert_authorized(
        prdb_engine::overlay::RowId {
            table: table.table_id,
            row: id(0xa1),
        },
        &projection,
        &[Some(ScalarValue::Uuid(concurrent_identity))],
        &table.column_ids,
    )?;
    let (left_result, right_result) = std::thread::scope(|scope| {
        let barrier = Arc::new(Barrier::new(2));
        let left_barrier = Arc::clone(&barrier);
        let right_barrier = Arc::clone(&barrier);
        let left_commit = scope.spawn(move || {
            left_barrier.wait();
            left.commit()
        });
        let right_commit = scope.spawn(move || {
            right_barrier.wait();
            right.commit()
        });
        (
            left_commit
                .join()
                .expect("left UUID commit thread panicked"),
            right_commit
                .join()
                .expect("right UUID commit thread panicked"),
        )
    });
    assert!(matches!(
        (&left_result, &right_result),
        (
            Ok(_),
            Err(prdb_engine::transaction::TransactionError::Commit(
                prdb_engine::commit::CommitError::UniqueViolation
            ))
        ) | (
            Err(prdb_engine::transaction::TransactionError::Commit(
                prdb_engine::commit::CommitError::UniqueViolation
            )),
            Ok(_)
        )
    ));
    let left_outcome = lookup_outcome(&database, id(0xa2), actor, 1)?
        .ok_or("left concurrent UUID commit has no durable outcome")?;
    let right_outcome = lookup_outcome(&database, id(0xa3), actor, 1)?
        .ok_or("right concurrent UUID commit has no durable outcome")?;
    assert_ne!(left_outcome.status, right_outcome.status);
    assert!(matches!(
        (left_outcome.status, right_outcome.status),
        (OutcomeStatus::Committed, OutcomeStatus::Aborted)
            | (OutcomeStatus::Aborted, OutcomeStatus::Committed)
    ));
    Ok(())
}
